package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Locale;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Single source of truth for the owner-household identity rule. Two owners count as the same
 * household when their last names match (compared case-insensitively, whitespace collapsed) and
 * their addresses match in their normalized form (see {@link OwnerAddress#normalize}: whitespace
 * collapsed, upper-cased, common abbreviations expanded). This class owns both the comparison
 * ({@link #sameHousehold}, built on {@link #normalize}) and the derivation of the stable shared
 * {@link #householdId} that identifies a household.
 *
 * <p>Used by {@link CheckOwnerHouseholdUnique} to reject a non-opted-in duplicate, and by
 * {@link AssignOwnerHousehold} to find the household's existing members and to compute the id they
 * share — so the definition of "same household" lives here and nowhere else.
 */
final class OwnerHousehold {

    private OwnerHousehold() {
    }

    /**
     * Reduces a value to its comparison form: trimmed, inner runs of whitespace collapsed to a
     * single space, and lower-cased. A {@code null} value yields an empty string.
     */
    static String normalize(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }

    /**
     * Tells whether an existing owner belongs to the household identified by the given last name and
     * address — the one place that defines what "same household" means. Last names are reduced
     * through {@link #normalize} and addresses through {@link OwnerAddress#normalize} before
     * comparison, so differently cased, spaced or abbreviated values that mean the same thing still
     * match.
     */
    static boolean sameHousehold(Owner existing, String lastName, String address) {
        return normalize(existing.getLastName()).equals(normalize(lastName))
                && OwnerAddress.normalize(existing.getAddress())
                        .equals(OwnerAddress.normalize(address));
    }

    /**
     * Derives the stable household identifier shared by every owner in the same household. Two
     * owners whose normalized last name and address match produce the same value, so the id can be
     * computed independently for each joining owner without coordinating through the database. The
     * value is {@code "HH-"} followed by the first 12 upper-case hex characters of the SHA-256 of
     * the normalized {@code "<lastName>|<address>"}.
     */
    static String householdId(String lastName, String address) {
        String key = normalize(lastName) + "|" + OwnerAddress.normalize(address);
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256")
                    .digest(key.getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < 6; i++) {
                sb.append(String.format("%02X", digest[i]));
            }
            return "HH-" + sb;
        }
        catch (NoSuchAlgorithmException ex) {
            throw new IllegalStateException("SHA-256 not available", ex);
        }
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import java.util.LinkedHashMap;
import java.util.Map;

/**
 * Single source of truth for the owner-telephone E.164 rule. Both {@link ValidateOwnerFields}
 * (which normalizes the submitted value) and {@link CheckOwnerTelephoneUnique} (which compares
 * against stored owners) convert through {@link #toE164} so the two can never drift apart.
 *
 * <p>The rule: strip spaces, dashes and brackets. If what remains starts with a '+', keep that
 * leading '+' and country code as-is. Otherwise assume Australian country code '+61', dropping a
 * single leading '0' from the national digits before prefixing. The result must be a '+' followed
 * by 8 to 15 digits; anything else cannot form valid E.164 and yields {@code null}.
 *
 * <p>The national-number length is then checked against the country calling code: '+61' requires
 * exactly 9 national digits and '+1' requires exactly 10. A number with the wrong national length
 * for its country code yields {@code null} (rejected as an invalid telephone). Country codes other
 * than these keep only the generic 8-to-15-digit bound.
 *
 * <p>Example: {@code "0412 345 678"} becomes {@code "+61412345678"}.
 */
final class OwnerTelephone {

    /**
     * Country calling code to required national-number length. Iteration order is longest code
     * first so a longer code is matched before a shorter one that is a prefix of it.
     */
    private static final Map<String, Integer> NATIONAL_LENGTH = new LinkedHashMap<>();

    static {
        NATIONAL_LENGTH.put("61", 9);
        NATIONAL_LENGTH.put("1", 10);
    }

    private OwnerTelephone() {
    }

    /**
     * Converts a submitted telephone to its E.164 form, or returns {@code null} when the value
     * cannot form a valid E.164 number.
     */
    static String toE164(String value) {
        if (value == null) {
            return null;
        }
        // Strip spaces, dashes and brackets; everything else must be a '+' or a digit.
        String cleaned = value.replaceAll("[\\s()\\-]", "");
        String digits;
        if (cleaned.startsWith("+")) {
            // Already international: keep the '+' and country code.
            digits = cleaned.substring(1);
        }
        else {
            // Assume '+61', dropping a single leading '0' from the national digits.
            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
            digits = "61" + national;
        }
        // Require 8 to 15 digits (and nothing but digits) after the '+'.
        if (!digits.matches("[0-9]{8,15}")) {
            return null;
        }
        // Check the national-number length against the country calling code.
        for (Map.Entry<String, Integer> entry : NATIONAL_LENGTH.entrySet()) {
            String code = entry.getKey();
            if (digits.startsWith(code)) {
                int nationalLength = digits.length() - code.length();
                return nationalLength == entry.getValue() ? "+" + digits : null;
            }
        }
        return "+" + digits;
    }
}

